=== src/mail/send.js
const { CATEGORIES } = require('./categories');

const outbox = [];

function sendMail({ user, template, category, message }) {
  const cat = CATEGORIES[category];
  if (!cat) throw new Error('unknown category ' + category);
  if (cat.suppressible && user.unsubscribed) return false;
  outbox.push({ to: user.email, template, category, message });
  return true;
}

module.exports = { sendMail, outbox };
