const test = require('node:test');
const assert = require('node:assert');
const { sendMail, outbox } = require('../src/mail/send');

const user = { email: 'u@example.test', locale: 'de', unsubscribed: true };

test('unsubscribed users get no account or marketing mail', () => {
  assert.strictEqual(sendMail({ user, template: 'welcome', category: 'account', message: {} }), false);
  assert.strictEqual(sendMail({ user, template: 'promo', category: 'marketing', message: {} }), false);
});

test('security mail always goes out', () => {
  assert.strictEqual(sendMail({ user, template: 'new-login', category: 'security', message: {} }), true);
  assert.strictEqual(outbox.at(-1).category, 'security');
});
